-- Sample guides: published ones in several niches, one high-risk guide
-- already approved by the expert, one waiting for an expert, and one draft
INSERT INTO guides (guide_id, author_id, title, category, summary, parts_list, precautions,
                    steps, estimated_cost, difficulty, risk_factor, status) VALUES
    (1, 5, 'Automatic Plant Watering System', 'GARDENING',
        'Water a potted plant automatically when the soil gets dry, using a soil moisture sensor and a small pump.',
        'Arduino Uno\nCapacitive soil moisture sensor\n5V relay module\n5V mini water pump and tubing\nJumper wires\n5V power supply',
        'Keep the Arduino and wires away from water.\nUse only a low voltage 5V pump.\nUnplug the power before changing any wiring.',
        '1. Push the moisture sensor into the soil and wire it to pin A0.\n2. Wire the relay input to pin 7 and the pump through the relay.\n3. Upload a sketch that turns the pump on when the reading shows dry soil.\n4. Put the tube in the pot and test it with dry soil.',
        850.00, 'BEGINNER', 'LOW', 'PUBLISHED'),
    (2, 4, 'Door Sensor Alarm with Buzzer', 'HOME_SECURITY',
        'Sound a buzzer whenever a door opens, using a magnetic reed switch and an Arduino Nano.',
        'Arduino Nano\nMagnetic reed switch\nActive buzzer\nOn/off switch\n9V battery and clip\nDouble-sided tape',
        'Mount the parts on the inside of the door only.\nRemove the battery when the alarm is not in use.',
        '1. Stick the reed switch on the frame and the magnet on the door.\n2. Wire the reed switch to pin 2 and the buzzer to pin 8.\n3. Upload a sketch that beeps when pin 2 goes HIGH.\n4. Close the door, arm the switch, and test it.',
        600.00, 'BEGINNER', 'LOW', 'PUBLISHED'),
    (3, 3, 'Rice Cooker Auto-Off Timer', 'FOOD_COOKING',
        'Turn a plain rice cooker off after a set time with a timer relay, so rice never burns while you study.',
        'Arduino Uno\n5V relay module rated for 10A at 230V\nRotary encoder\n0.96 inch OLED display\nEnclosed project box\nPower cord with plug and socket',
        'This guide switches 230V mains power. Work only when everything is unplugged.\nKeep all mains wiring inside a closed box.\nAsk an adult or an electrician to check the wiring before first use.',
        '1. Mount the relay and the socket inside the project box.\n2. Wire the live line through the relay contacts.\n3. Wire the encoder and OLED to the Arduino and upload the timer sketch.\n4. Close the box, plug in the rice cooker, and test with a 1 minute timer.',
        900.00, 'INTERMEDIATE', 'HIGH', 'PENDING'),
    (4, 3, 'Study Timer with Break Reminder', 'STUDIES',
        'A small desk timer that reminds you to take a break every 25 minutes.',
        'Arduino Nano\nBuzzer\nPush button',
        '',
        '1. Wire the button to pin 2.',
        NULL, 'BEGINNER', 'LOW', 'DRAFT'),
    (5, 4, 'Smart Power Strip with Usage Monitor', 'ENERGY_SAVING',
        'Turn an ordinary power strip into a Wi-Fi controlled one that shows how much electricity each appliance uses, so you can spot devices that waste power.',
        'ESP32 development board\nACS712 current sensor (one per outlet)\n4-channel 10A relay module\nPower strip with 3 outlets\n5V phone charger for the ESP32\nEnclosed project box',
        'This guide works with 230V mains power. Unplug everything before opening the strip.\nKeep high voltage parts inside the closed box.\nHave an expert or electrician check the wiring before first use.',
        '1. Open the power strip and plan where each relay and sensor goes.\n2. Wire each outlet''s live line through one relay and one current sensor.\n3. Connect the sensors to the ESP32 analog pins and the relays to digital pins.\n4. Upload the sketch and connect the ESP32 to your Wi-Fi.\n5. Close the box and check the readings in the phone dashboard.',
        1450.00, 'INTERMEDIATE', 'HIGH', 'PUBLISHED'),
    (6, 6, 'Motion-Activated Hallway Light', 'ENERGY_SAVING',
        'Light up a dark hallway only when someone walks by, using a PIR sensor and an LED strip.',
        'PIR motion sensor\n12V LED strip (1 meter)\nMOSFET module\n12V power adapter\nArduino Nano',
        'Use a proper 12V adapter and never connect the LED strip to mains.\nKeep the MOSFET module ventilated.',
        '1. Mount the PIR sensor at waist height facing the hallway.\n2. Wire the LED strip through the MOSFET module.\n3. Upload a sketch that turns the strip on for 30 seconds after motion.\n4. Adjust the sensor sensitivity knob until it works reliably.',
        700.00, 'BEGINNER', 'MODERATE', 'PUBLISHED'),
    (7, 4, 'Laundry Done Notifier', 'HOUSEKEEPING',
        'Get a phone alert when the washing machine stops shaking, so clothes do not sit wet in the drum.',
        'ESP8266 board\nSW-420 vibration sensor\nUSB power bank\nVelcro strips',
        'Stick the device on the top of the machine, away from water.\nDo not open the washing machine casing.',
        '1. Wire the vibration sensor to pin D2.\n2. Upload a sketch that sends a notification after 3 minutes of no vibration.\n3. Attach the device on top of the machine with Velcro.\n4. Run a short wash cycle to test it.',
        550.00, 'BEGINNER', 'LOW', 'PUBLISHED'),
    (8, 6, 'Bedroom Air Quality Monitor', 'HEALTH_WELLNESS',
        'Show the room''s air quality, temperature and humidity on a small screen, with a warning light when air gets stuffy.',
        'ESP32 development board\nMQ-135 gas sensor\nDHT22 temperature and humidity sensor\n0.96 inch OLED display\nRGB LED',
        'The MQ-135 heater gets warm, so keep it away from paper and fabric.\nPower it with a phone charger, not a laptop, for steady readings.',
        '1. Wire the MQ-135 to an analog pin and the DHT22 to pin 4.\n2. Connect the OLED with SDA and SCL.\n3. Upload the sketch and let the gas sensor warm up for 24 hours.\n4. Set the warning level after a day of normal readings.',
        1200.00, 'INTERMEDIATE', 'MODERATE', 'PUBLISHED'),
    (9, 3, 'Pet Water Bowl Refill Alert', 'PETS',
        'Beep when your pet''s water bowl runs low, using a simple water level sensor.',
        'Arduino Nano\nWater level sensor\nBuzzer\nBattery pack',
        'Keep the Arduino in a sealed box beside the bowl.\nOnly the sensor tip should touch the water.',
        '1. Clip the water level sensor to the side of the bowl.\n2. Wire the sensor to A0 and the buzzer to pin 8.\n3. Upload a sketch that beeps when the level drops below a third.\n4. Test it by draining the bowl slowly.',
        500.00, 'BEGINNER', 'LOW', 'PUBLISHED'),
    (10, 6, 'Solar Phone Charging Station', 'ENERGY_SAVING',
        'Charge phones from a small solar panel and battery, and show the battery level on an LED bar.',
        '10W solar panel\nTP4056 charger modules\n18650 battery holder and cells\nUSB boost converter\nLED bar graph',
        'Use protected 18650 cells and never short the battery terminals.\nDo not leave charging cells in direct sun inside a closed box.',
        '1. Connect the solar panel to the charger module.\n2. Wire the battery holder and the boost converter.\n3. Add the LED bar graph to show the battery level.\n4. Test charging a phone on a sunny day.',
        1200.00, 'INTERMEDIATE', 'MODERATE', 'PUBLISHED');

